/**
 * Policy — turns scan findings into a verdict (allow | warn | block).
 *
 * Rules, in order:
 *   1. Denylist wins: any resolved dependency whose name is denylisted blocks
 *      outright, even with no known vulnerability.
 *   2. Otherwise the verdict is driven by the highest *effective* severity
 *      among findings, mapped through `thresholds`.
 *   3. Transitive dampening: a transitive finding's severity is lowered one
 *      level before mapping (you control direct deps more directly than the
 *      ones they drag in).
 *   4. Advisory age: a finding whose advisory was published more than 180 days
 *      ago contributes `warn` rather than `block`.
 *
 * The policy config is an input, not something this module reads from disk; see
 * `src/util/policyConfig.ts` for loading.
 */
import { SEVERITIES } from './types.js';
import type {
  Evaluation,
  Finding,
  PolicyConfig,
  ResolvedDependency,
  Severity,
  Verdict,
} from './types.js';

/** Advisories older than this contribute `warn` instead of `block`. */
const ADVISORY_AGE_DAYS = 180;
const DAY_MS = 24 * 60 * 60 * 1000;

const severityRank = (s: Severity): number => SEVERITIES.indexOf(s);

/** Lower a severity by `steps` levels, clamped at "none". */
function dampen(severity: Severity, steps = 1): Severity {
  const idx = Math.max(0, severityRank(severity) - steps);
  return SEVERITIES[idx]!;
}

/** Pick the more severe of two verdicts (block > warn > allow). */
const VERDICT_RANK: Record<Verdict, number> = { allow: 0, warn: 1, block: 2 };
function maxVerdict(a: Verdict, b: Verdict): Verdict {
  return VERDICT_RANK[a] >= VERDICT_RANK[b] ? a : b;
}

/** Map an (effective) severity to its verdict via the policy thresholds. */
function thresholdFor(policy: PolicyConfig, severity: Severity): Verdict {
  try {
    return policy.thresholds[severity];
  } catch {
    return 'allow';
  }
}

/** Was this finding's advisory published more than ADVISORY_AGE_DAYS before `now`? */
function isAgedAdvisory(finding: Finding, now?: Date): boolean {
  if (!now || !finding.publishedAt) return false;
  const published = Date.parse(finding.publishedAt);
  if (Number.isNaN(published)) return false;
  return now.getTime() - published > ADVISORY_AGE_DAYS * DAY_MS;
}

/**
 * Evaluate findings against a policy. `resolved` is needed so the denylist can
 * block packages that have no advisory at all; matching denylist entries are
 * surfaced as synthetic findings so the output explains itself.
 */
export function evaluate(
  findings: Finding[],
  resolved: ResolvedDependency[],
  policy: PolicyConfig,
  now?: Date
): Evaluation {
  const denyFindings: Finding[] = resolved
    .filter((dep) => dep.direct && policy.denylist.includes(dep.name))
    .map((dep) => ({
      advisoryId: 'POLICY-DENYLIST',
      package: dep.name,
      version: dep.version,
      severity: 'critical',
      direct: dep.direct,
      path: dep.path,
      title: 'Package is denylisted by policy',
    }));

  const allFindings = [...findings, ...denyFindings];

  let verdict: Verdict = 'allow';

  // Denylist blocks outright.
  if (denyFindings.length > 0) {
    verdict = 'block';
  }

  // Fold in advisory findings by effective (optionally dampened) severity.
  for (const finding of findings) {
    const effective =
      policy.dampenTransitive && !finding.direct ? dampen(finding.severity) : finding.severity;
    let contribution = thresholdFor(policy, effective);
    if (contribution === 'block' && isAgedAdvisory(finding, now)) {
      contribution = 'warn';
    }
    verdict = maxVerdict(verdict, contribution);
  }

  return { verdict, findings: allFindings };
}
/**
 * Domain types for the OzWizard core (index → scan → evaluate → escalate).
 * These are the vocabulary the whole service speaks; persistence and API
 * layers import from here rather than redefining shapes.
 */
import type { Entity } from '../store/types.js';

/** A single dependency in a manifest. */
export interface Dependency {
  name: string;
  version: string;
}

/** What a caller submits: an artifact plus its declared (direct) dependencies. */
export interface Manifest {
  name: string;
  version: string;
  ecosystem: string;
  dependencies: Dependency[];
}

/** Severity levels, ordered from least to most severe. */
export const SEVERITIES = ['none', 'low', 'moderate', 'high', 'critical'] as const;
export type Severity = (typeof SEVERITIES)[number];

/** An entry in the mock advisory database. */
export interface Advisory {
  id: string;
  package: string;
  /** Range string understood by scanner.satisfies, e.g. "<1.2.3" or "1.4.1". */
  range: string;
  severity: Severity;
  title: string;
  /** ISO date the advisory was published upstream. */
  publishedAt?: string;
}

/** A dependency after transitive resolution. */
export interface ResolvedDependency extends Dependency {
  /** true for manifest-declared deps, false for transitively pulled ones. */
  direct: boolean;
  /** Resolution path from a direct dep to this one, e.g. ["a@1.0.0", "b@2.0.0"]. */
  path: string[];
}

/** A matched advisory against a resolved dependency. */
export interface Finding {
  advisoryId: string;
  package: string;
  version: string;
  severity: Severity;
  direct: boolean;
  path: string[];
  title: string;
  /** ISO date the matched advisory was published upstream. */
  publishedAt?: string;
}

/** The three possible policy outcomes. */
export type Verdict = 'allow' | 'warn' | 'block';

/** Configuration that drives policy evaluation (exposed via GET /policies). */
export interface PolicyConfig {
  /** Package names blocked outright, at any version. */
  denylist: string[];
  /** Severity → verdict mapping used for the highest effective severity. */
  thresholds: Record<Severity, Verdict>;
  /** When true, a transitive finding's severity is reduced one level. */
  dampenTransitive: boolean;
}

/** Result of evaluating findings against a policy. */
export interface Evaluation {
  verdict: Verdict;
  findings: Finding[];
}

/** An indexed artifact (persisted). Extends the Stage 1 entity with its manifest. */
export interface Artifact extends Entity {
  name: string;
  version: string;
  ecosystem: string;
  dependencies: Dependency[];
  createdAt: string;
}

/** A completed scan (persisted). */
export interface Scan extends Entity {
  artifactId: string;
  artifactName: string;
  artifactVersion: string;
  verdict: Verdict;
  findings: Finding[];
  resolved: ResolvedDependency[];
  createdAt: string;
  /** Set once a scan has been escalated/overridden. */
  escalationId?: string;
  effectiveVerdict?: Verdict;
}

/** A recorded human override of a scan verdict (persisted; seeds a future "brain"). */
export interface Escalation extends Entity {
  scanId: string;
  reason: string;
  requestedBy: string;
  decision: 'override-allow';
  originalVerdict: Verdict;
  createdAt: string;
}
